from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    FAST_PERIOD = 5
    SLOW_PERIOD = 20

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(-100, 100, timedelta(days=0), timedelta(days=365))
        self.option_symbol = option.Symbol

        self.closes = deque(maxlen=self.SLOW_PERIOD)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_signal = False

        self.held_contract = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.equity_liquidation_order_id = None
        self.block_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(9, 31),
            self.ProcessExpiration
        )

        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(15, 45),
            self.ProcessTimeStop
        )

    def OnFiveMinuteBar(self, sender, bar):
        self.closes.append(float(bar.Close))

        if len(self.closes) < self.SLOW_PERIOD:
            return

        prices = list(self.closes)
        fast = sum(prices[-self.FAST_PERIOD:]) / self.FAST_PERIOD
        slow = sum(prices) / self.SLOW_PERIOD

        if self.previous_fast is not None and self.previous_slow is not None:
            eligible_time = (
                (bar.EndTime.hour > 9 or (bar.EndTime.hour == 9 and bar.EndTime.minute >= 45))
                and (bar.EndTime.hour < 14 or (bar.EndTime.hour == 14 and bar.EndTime.minute <= 30))
            )

            if (
                eligible_time
                and self.previous_fast <= self.previous_slow
                and fast > slow
            ):
                self.pending_entry_signal = True

        self.previous_fast = fast
        self.previous_slow = slow

    def OnData(self, data):
        self.HandleUnexpectedSpyHolding()

        if self.held_contract is not None and self.Portfolio[self.held_contract].Invested:
            self.CheckProfitTarget(data)

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.TryEnter(data)

    def TryEnter(self, data):
        if self.block_entry_date == self.Time.date():
            self.Debug("Skipped entry: expiration processing is active today.")
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Invested:
            return

        if self.entry_order_id is not None or self.exit_order_id is not None:
            return

        if self.Portfolio.Invested:
            return

        chain = self.GetCurrentOptionChain(data)
        if chain is None:
            self.Debug("Skipped entry: no SPY option chain in current Slice.")
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        contracts = list(chain.Contracts.Values)

        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        expiry = eligible_expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = min(candidates, key=lambda c: (float(c.Strike), str(c.Symbol)))

        self.held_contract = selected.Symbol
        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol}, expiry {expiry}, strike {selected.Strike}."
        )

    def CheckProfitTarget(self, data):
        if self.exit_order_id is not None or self.entry_price is None:
            return

        chain = self.GetCurrentOptionChain(data)
        if chain is None:
            return

        contract = None
        for candidate in chain.Contracts.Values:
            if candidate.Symbol == self.held_contract:
                contract = candidate
                break

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self.CancelOpenExitOrder()
            ticket = self.MarketOrder(
                self.held_contract,
                -self.Portfolio[self.held_contract].Quantity
            )
            self.exit_order_id = ticket.OrderId
            self.Debug(
                f"Profit-target exit submitted: {self.held_contract}, midpoint {midpoint:.2f}."
            )

    def ProcessTimeStop(self):
        if self.held_contract is None or not self.Portfolio[self.held_contract].Invested:
            return

        expiry = self.held_contract.ID.Date.date()
        if self.IsTradingDayImmediatelyBefore(expiry):
            self.CancelOpenExitOrder()
            ticket = self.MarketOrder(
                self.held_contract,
                -self.Portfolio[self.held_contract].Quantity
            )
            self.exit_order_id = ticket.OrderId
            self.Debug(f"Pre-expiration time-stop exit submitted: {self.held_contract}.")

    def ProcessExpiration(self):
        if self.held_contract is None or not self.Portfolio[self.held_contract].Invested:
            return

        expiry = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry:
            self.block_entry_date = self.Time.date()
            self.CancelOpenExitOrder()
            ticket = self.MarketOrder(
                self.held_contract,
                -self.Portfolio[self.held_contract].Quantity
            )
            self.exit_order_id = ticket.OrderId
            self.Debug(f"Expiration-protection exit submitted: {self.held_contract}.")

    def IsTradingDayImmediatelyBefore(self, expiry_date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        next_date = self.Time.date() + timedelta(days=1)

        while next_date <= expiry_date:
            try:
                is_open = exchange_hours.IsDateOpen(next_date, False)
            except Exception:
                is_open = next_date.weekday() < 5

            if is_open:
                return next_date == expiry_date

            next_date += timedelta(days=1)

        return False

    def HandleUnexpectedSpyHolding(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            self.equity_liquidation_order_id = None
            return

        if self.equity_liquidation_order_id is None:
            ticket = self.MarketOrder(self.spy, -quantity)
            self.equity_liquidation_order_id = ticket.OrderId
            self.Debug(
                f"Unexpected SPY exercise/assignment holding detected; liquidation submitted for {quantity} shares."
            )

    def CancelOpenExitOrder(self):
        if self.exit_order_id is None:
            return

        order = self.Transactions.GetOrderById(self.exit_order_id)
        if order is not None and order.Status in [OrderStatus.New, OrderStatus.Submitted]:
            self.Transactions.CancelOrder(self.exit_order_id)

    def GetCurrentOptionChain(self, data):
        if self.option_symbol in data.OptionChains:
            return data.OptionChains[self.option_symbol]

        for chain in data.OptionChains.Values:
            if chain.Underlying.Symbol == self.spy:
                return chain

        return None

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_price:.2f}."
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug("Entry order did not fill; clearing pending contract.")
                self.entry_order_id = None
                self.held_contract = None
                self.entry_price = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {float(order_event.FillPrice):.2f}."
                )
                self.exit_order_id = None
                self.held_contract = None
                self.entry_price = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None

