from AlgorithmImports import *
from datetime import timedelta, time


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):
    FAST_PERIOD = 5
    SLOW_PERIOD = 20

    def initialize(self):
        self.set_start_date(2023, 4, 1)
        self.set_end_date(2026, 6, 30)
        self.set_cash(100000)
        self.set_time_zone(TimeZones.NEW_YORK)

        self.spy = self.add_equity(
            "SPY",
            Resolution.MINUTE,
            data_normalization_mode=DataNormalizationMode.RAW
        ).symbol

        option = self.add_option("SPY", Resolution.MINUTE)
        option.set_filter(
            lambda universe: universe.include_weeklys()
            .strikes(-100, 100)
            .expiration(0, 365)
        )
        self.option_symbol = option.symbol

        self.fast_closes = RollingWindow[float](self.FAST_PERIOD)
        self.slow_closes = RollingWindow[float](self.SLOW_PERIOD)
        self.previous_fast = None
        self.previous_slow = None

        self.pending_entry_signal = False
        self.entry_order_id = None
        self.exit_order_id = None
        self.held_contract = None
        self.entry_fill_price = None
        self.blocked_entry_date = None
        self.spy_liquidation_order_id = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.data_consolidated += self.on_five_minute_bar
        self.subscription_manager.add_consolidator(self.spy, consolidator)

    def on_data(self, data):
        self.handle_unexpected_spy_position()

        if self.held_contract is not None:
            self.process_expiration_safety()
            self.process_time_stop()
            self.process_profit_target(data)

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.try_enter_call(data)

    def on_five_minute_bar(self, sender, bar):
        self.fast_closes.add(bar.close)
        self.slow_closes.add(bar.close)

        if not (self.fast_closes.is_ready and self.slow_closes.is_ready):
            return

        fast = sum(self.fast_closes[i] for i in range(self.FAST_PERIOD)) / self.FAST_PERIOD
        slow = sum(self.slow_closes[i] for i in range(self.SLOW_PERIOD)) / self.SLOW_PERIOD

        crossed_up = (
            self.previous_fast is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        end_time = bar.end_time.time()
        if crossed_up and time(9, 45) <= end_time <= time(14, 30):
            self.pending_entry_signal = True

    def try_enter_call(self, data):
        if self.blocked_entry_date == self.time.date():
            return

        if self.held_contract is not None or self.entry_order_id is not None:
            return

        if self.exit_order_id is not None:
            return

        chain = data.option_chains.get(self.option_symbol)
        if chain is None:
            self.debug("Skipped entry: no SPY option chain.")
            return

        contracts = [contract for contract in chain if contract.right == OptionRight.CALL]
        if not contracts:
            self.debug("Skipped entry: no call contracts.")
            return

        minimum_expiry = self.time.date() + timedelta(days=7)
        eligible_expiries = sorted(
            {contract.expiry.date() for contract in contracts
             if contract.expiry.date() >= minimum_expiry}
        )

        if not eligible_expiries:
            self.debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        expiry = eligible_expiries[0]
        minimum_strike = self.securities[self.spy].price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.expiry.date() == expiry and contract.strike >= minimum_strike
        ]

        if not candidates:
            self.debug("Skipped entry: no qualifying OTM call at selected expiration.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.strike, str(contract.symbol))
        )[0]

        ticket = self.market_order(selected.symbol, 1, tag="Bullish five-minute crossover entry")
        self.entry_order_id = ticket.order_id

    def process_profit_target(self, data):
        if self.exit_order_id is not None:
            return

        quote = data.quote_bars.get(self.held_contract)
        if quote is None or quote.bid is None or quote.ask is None:
            return

        bid = quote.bid.close
        ask = quote.ask.close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.submit_exit("50% profit target")

    def process_time_stop(self):
        if self.exit_order_id is not None:
            return

        expiry = self.held_contract.id.date.date()
        previous_trading_day = self.securities[self.held_contract].exchange.hours.get_previous_trading_day(expiry)

        if self.time.date() == previous_trading_day.date() and self.time.time() >= time(15, 45):
            self.submit_exit("15:45 pre-expiration time stop")

    def process_expiration_safety(self):
        expiry = self.held_contract.id.date.date()
        if self.time.date() >= expiry:
            self.blocked_entry_date = self.time.date()
            if self.exit_order_id is None:
                self.submit_exit("Expiration safety liquidation")

    def submit_exit(self, reason):
        if self.held_contract is None:
            return

        for order in self.transactions.get_open_orders(self.held_contract):
            self.transactions.cancel_order(order.id)

        quantity = self.portfolio[self.held_contract].quantity
        if quantity != 0:
            ticket = self.market_order(
                self.held_contract,
                -quantity,
                tag=reason
            )
            self.exit_order_id = ticket.order_id
            self.debug("Exit submitted: " + reason)

    def handle_unexpected_spy_position(self):
        quantity = self.portfolio[self.spy].quantity
        if quantity == 0 or self.spy_liquidation_order_id is not None:
            return

        ticket = self.market_order(
            self.spy,
            -quantity,
            tag="Unexpected exercise or assignment cleanup"
        )
        self.spy_liquidation_order_id = ticket.order_id
        self.debug("Unexpected SPY exercise/assignment position: liquidation submitted.")

    def on_order_event(self, order_event):
        if order_event.order_id == self.entry_order_id:
            if order_event.status == OrderStatus.FILLED:
                self.held_contract = order_event.symbol
                self.entry_fill_price = order_event.fill_price
                self.entry_order_id = None
                self.debug(
                    "Entry filled: {0} @ {1:.2f}".format(
                        self.held_contract,
                        self.entry_fill_price
                    )
                )
            elif order_event.status in (OrderStatus.CANCELED, OrderStatus.INVALID):
                self.entry_order_id = None

        if order_event.order_id == self.exit_order_id:
            if order_event.status == OrderStatus.FILLED:
                self.debug(
