        self.fast_values.add(self.fast.current.value)
        self.slow_values.add(self.slow.current.value)

        if self.fast_values.count < 2 or self.slow_values.count < 2:
            return

        bar_time = self.time
        if bar_time.date() in self.no_entry_dates:
            return

        if not (bar_time.hour > 9 or (bar_time.hour == 9 and bar_time.minute >= 45)):
            return

        if not (bar_time.hour < 14 or (bar_time.hour == 14 and bar_time.minute <= 30)):
            return

        bullish_cross = (
            self.fast_values[1] <= self.slow_values[1]
            and self.fast_values[0] > self.slow_values[0]
        )

        if bullish_cross:
            self.try_enter()

    def try_enter(self):
        if self.entry_ticket is not None and self.entry_ticket.status in (
            OrderStatus.NEW, OrderStatus.SUBMITTED, OrderStatus.PARTIALLY_FILLED
        ):
            return

        if self.held_contract is not None and self.portfolio[self.held_contract].invested:
            return

        if self.portfolio[self.spy].invested:
            self.debug("Unexpected SPY position detected; liquidating.")
            self.market_order(self.spy, -self.portfolio[self.spy].quantity)
            return

        chain = self.current_slice.option_chains.get(self.option_symbol)
        if chain is None:
            self.debug("Entry skipped: no SPY option chain in Slice.")
            return

        spy_price = self.securities[self.spy].price
        if spy_price <= 0:
            self.debug("Entry skipped: SPY price unavailable.")
            return

        minimum_expiry = self.time.date() + timedelta(days=7)
        expirations = sorted({
            contract.expiry.date()
            for contract in chain
            if contract.right == OptionRight.CALL and contract.expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.debug("Entry skipped: no qualifying expiration.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01
        candidates = [
            contract for contract in chain
            if contract.right == OptionRight.CALL
            and contract.expiry.date() == selected_expiry
            and contract.strike >= minimum_strike
        ]

        if not candidates:
            self.debug("Entry skipped: no qualifying call strike.")
            return

        candidates.sort(key=lambda contract: (contract.strike, str(contract.symbol)))
        contract = candidates[0]

        self.held_contract = contract.symbol
        self.expiration_date = contract.expiry.date()
        self.entry_price = None
        self.exit_ticket = None
        self.entry_ticket = self.market_order(contract.symbol, 1)
        self.debug(f"Entry submitted: {contract.symbol}")

