        if self.portfolio[self.spy].invested:
            self.debug("Unexpected SPY exercise/assignment position; liquidating.")
            self.market_order(self.spy, -self.portfolio[self.spy].quantity)

        if self.held_contract is None:
            return

        holding = self.portfolio[self.held_contract]
        if not holding.invested:
            return

        if self.time.date() >= self.expiration_date:
            self.no_entry_dates.add(self.time.date())
            self.submit_exit("expiration protection")
            return

        if self.is_pre_expiration_time_stop():
            self.submit_exit("pre-expiration time stop")
            return

        if self.entry_price is None:
            return

        security = self.securities.get(self.held_contract)
        if security is None:
            return

        bid = security.bid_price
        ask = security.ask_price
        if bid > 0 and ask > 0:
            midpoint = (bid + ask) / 2.0
            if midpoint >= self.entry_price * 1.50:
                self.submit_exit("profit target")

    def is_pre_expiration_time_stop(self):
        if self.time.hour != 15 or self.time.minute != 45:
            return False

        exchange_hours = self.securities[self.spy].exchange.hours
        previous_open = exchange_hours.get_previous_market_open(
            self.expiration_date,
            False
        )
        return self.time.date() == previous_open.date()

    def submit_exit(self, reason):
        if self.held_contract is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.status in (
            OrderStatus.NEW, OrderStatus.SUBMITTED, OrderStatus.PARTIALLY_FILLED
        ):
            return

        for ticket in self.transactions.get_open_order_tickets():
            if ticket.symbol == self.held_contract:
                ticket.cancel("Replacing open exit with market liquidation.")

        quantity = self.portfolio[self.held_contract].quantity
        if quantity != 0:
            self.exit_ticket = self.market_order(self.held_contract, -quantity)
            self.debug(f"Exit submitted ({reason}): {self.held_contract}")

    def on_order_event(self, order_event):
        if self.held_contract is None:
            return

        if order_event.symbol != self.held_contract:
            return

        if order_event.status == OrderStatus.FILLED:
            if order_event.direction == OrderDirection.BUY:
                self.entry_price = order_event.fill_price
                self.debug(
                    f"Entry filled: {self.held_contract} at {self.entry_price:.2f}"
                )
            elif order_event.direction == OrderDirection.SELL:
                self.debug(
                    f"Exit filled: {self.held_contract} at {order_event.fill_price:.2f}"
                )
                if not self.portfolio[self.held_contract].invested:
                    self.held_contract = None
                    self.entry_price = None
                    self.expiration_date = None
                    self.entry_ticket = None
                    self.exit_ticket = None

