            Resolution.Minute,
            fill_forward=False
        ).Symbol
        self.Securities[self.option_symbol].SetFilter(
            -100, 100, timedelta(0), timedelta(days=180)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.five_minute_closes = deque(maxlen=self.slow_period)

        self.previous_fast = None
        self.previous_slow = None

        self.current_session_date = None
        self.expected_five_minute_end = None
        self.five_minute_parts = []

        self.active_contract = None
        self.entry_ticket_id = None
        self.exit_ticket_id = None
        self.entry_fill_price = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()

        if self.active_contract is not None:
            expiry_date = self.active_contract.ID.Date.date()
            if self.Time.date() >= expiry_date:
                self.no_entry_date = self.Time.date()
                if self.Portfolio[self.active_contract].Quantity != 0:
                    self.Debug(
                        f"Expiration handling: liquidating {self.active_contract}"
                    )
                    self._submit_exit("Expiration liquidation")

            self._evaluate_exit(slice)

        if slice.Bars.ContainsKey(self.spy):
            self._update_five_minute_bars(slice.Bars[self.spy], slice)

    def _update_five_minute_bars(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime
        bar_date = end_time.date()
        regular_open = time(9, 31)
        regular_close = time(16, 0)

        if end_time.time() < regular_open or end_time.time() > regular_close:
            return

        if self.current_session_date != bar_date:
            self.current_session_date = bar_date
            self.expected_five_minute_end = None
            self.five_minute_parts = []

        total_minutes = end_time.hour * 60 + end_time.minute
        rounded_end_minutes = ((total_minutes + 4) // 5) * 5
        candidate_end = datetime.combine(
            bar_date,
            time(rounded_end_minutes // 60, rounded_end_minutes % 60)
        )

        if candidate_end < datetime.combine(bar_date, time(9, 35)):
            return

        if self.expected_five_minute_end is None:
            self.expected_five_minute_end = candidate_end

        while candidate_end > self.expected_five_minute_end:
            self.five_minute_parts = []
            self.expected_five_minute_end += timedelta(minutes=5)

        if candidate_end != self.expected_five_minute_end:
            return

        self.five_minute_parts.append(bar)

        if end_time != self.expected_five_minute_end:
            return

        expected_start = self.expected_five_minute_end - timedelta(minutes=4)
        expected_times = [
            expected_start + timedelta(minutes=i) for i in range(5)
        ]

        actual_times = [x.EndTime for x in self.five_minute_parts]
        if actual_times == expected_times:
            self._on_completed_five_minute_bar(
                self.five_minute_parts[-1].Close,
                self.expected_five_minute_end,
                slice
            )

        self.five_minute_parts = []
        self.expected_five_minute_end += timedelta(minutes=5)

    def _on_completed_five_minute_bar(
        self,
        close: float,
        bar_end: datetime,
        slice: Slice
    ):
        self.five_minute_closes.append(close)

        if len(self.five_minute_closes) < self.slow_period:
            return

        values = list(self.five_minute_closes)
        fast = sum(values[-self.fast_period:]) / self.fast_period
        slow = sum(values) / self.slow_period

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

