            self.Debug("Skipped entry: no current SPY price.")
            return

        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped entry: no SPY option chain in Slice.")
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chain = slice.OptionChains[self.option_symbol]
        current_date = self.Time.date()

        valid_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - current_date).days >= 7
        })

        if not valid_expirations:
            self.Debug("Skipped entry: no expiration at least seven calendar days out.")
            return

        selected_expiry = valid_expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"Skipped entry: no qualifying call for {selected_expiry}."
            )
            return

        selected = min(candidates, key=lambda x: (x.Strike, str(x.Symbol)))
        self.active_contract = selected.Symbol
        ticket = self.MarketOrder(
            self.active_contract,
            1,
            tag="Bullish five-minute MA crossover entry"
        )
        self.entry_ticket_id = ticket.OrderId
        self.entry_fill_price = None
        self.Debug(f"Entry submitted: {self.active_contract}")

    def _evaluate_exit(self, slice: Slice):
        if self.active_contract is None:
            return

        quantity = self.Portfolio[self.active_contract].Quantity
        if quantity == 0:
            return

        expiry_date = self.active_contract.ID.Date.date()
        if self.Time.date() == self._previous_trading_day(expiry_date):
            if self.Time.time() == time(15, 45):
                self._submit_exit("Pre-expiration time stop")
                return

        if self.entry_fill_price is None or self._has_open_exit_order():
            return

        bid = ask = 0
        if slice.QuoteBars.ContainsKey(self.active_contract):
            quote = slice.QuoteBars[self.active_contract]
            bid = quote.Bid.Close if quote.Bid is not None else 0
            ask = quote.Ask.Close if quote.Ask is not None else 0

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2
        if midpoint >= self.entry_fill_price * 1.5:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if self.active_contract is None:
            return

        quantity = self.Portfolio[self.active_contract].Quantity
        if quantity == 0 or self._has_open_exit_order():
            return

        for order in self.Transactions.GetOpenOrders(self.active_contract):
            self.Transactions.CancelOrder(order.Id, "Replacing with exit market order")

        ticket = self.MarketOrder(
            self.active_contract,
            -quantity,
            tag=reason
        )
        self.exit_ticket_id = ticket.OrderId
        self.Debug(f"Exit submitted: {self.active_contract}; {reason}")

    def _previous_trading_day(self, expiry_date):
        day = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(day):
            day -= timedelta(days=1)

        return day

    def _has_open_exit_order(self):
        return (
            self.exit_ticket_id is not None
            and self._has_open_order(self.exit_ticket_id)
        )

    def _has_open_order(self, order_id):
        ticket = self.Transactions.GetOrderTicket(order_id)
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted,
            OrderStatus.CancelPending
        )

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        has_open_spy_order = any(
            order.Symbol == self.spy
            for order in self.Transactions.GetOpenOrders(self.spy)
        )

        if not has_open_spy_order:
            self.Debug(
                f"Unexpected SPY position from exercise/assignment: {quantity}; liquidating."
            )
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise/assignment cleanup"
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.entry_fill_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {self.entry_fill_price}"
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"Entry failed: {order_event.Symbol}")
                self.entry_ticket_id = None
                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.active_contract = None
                    self.entry_fill_price = None

        if self.exit_ticket_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {order_event.FillPrice}"
                )
                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.active_contract = None
                    self.entry_fill_price = None
                    self.entry_ticket_id = None
                    self.exit_ticket_id = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_ticket_id = None

