        if not slice.Bars.ContainsKey(self.spy):
            return

        bar = slice.Bars[self.spy]
        start = bar.Time
        minutes_since_midnight = start.hour * 60 + start.minute

        regular_open = 9 * 60 + 30
        regular_close = 16 * 60

        if minutes_since_midnight < regular_open or minutes_since_midnight >= regular_close:
            return

        bucket_minute = regular_open + ((minutes_since_midnight - regular_open) // 5) * 5
        bucket_start = start.replace(
            hour=bucket_minute // 60,
            minute=bucket_minute % 60,
            second=0,
            microsecond=0
        )
        bucket_end = bucket_start + timedelta(minutes=5)

        if bucket_start not in self.five_minute_buckets:
            self.five_minute_buckets[bucket_start] = []

        self.five_minute_buckets[bucket_start].append(bar)

        if bar.EndTime == bucket_end:
            minute_bars = self.five_minute_buckets.pop(bucket_start, [])
            expected_times = {
                bucket_start + timedelta(minutes=i)
                for i in range(5)
            }
            actual_times = {x.Time for x in minute_bars}

            if len(minute_bars) != 5 or actual_times != expected_times:
                return

            close = minute_bars[-1].Close
            self._on_completed_five_minute_bar(bucket_end, close, slice)

    def _on_completed_five_minute_bar(self, end_time, close, slice):
        prior_ready = self.previous_ready
        prior_fast = self.previous_fast
        prior_slow = self.previous_slow

        self.fast.Update(end_time, close)
        self.slow.Update(end_time, close)

        current_ready = self.fast.IsReady and self.slow.IsReady
        bullish_crossover = (
            prior_ready
            and current_ready
            and prior_fast <= prior_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        self.previous_ready = current_ready
        self.previous_fast = self.fast.Current.Value
        self.previous_slow = self.slow.Current.Value

        if not bullish_crossover:
            return

        current_time = end_time.time()
        if current_time < time(9, 45) or current_time > time(14, 30):
            return

        self._try_enter(slice, close)

    def _try_enter(self, slice, spy_price):
        if self.Time.date() in self.no_entry_dates:
            return

        if self.held_option is not None or self.entry_order_id is not None:
            return

        if self.Portfolio.Invested:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no SPY option chain")
            return

        today = self.Time.date()
        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if (contract.Expiry.date() - today).days >= 7
        })

        if not eligible_expiries:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away")
            return

        expiry = eligible_expiries[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol} exp {expiry} strike {selected.Strike}"
        )

    def _handle_option_exit(self, slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_order_id is not None:
            return

        if self.Portfolio[self.held_option].Quantity <= 0:
            return

        if self._is_pre_expiration_time_stop():
            self._submit_exit("pre-expiration time stop")
            return

        quote = slice.QuoteBars.get(self.held_option)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.50:
            self._submit_exit("50% profit target")

    def _is_pre_expiration_time_stop(self):
        if self.held_expiry is None:
            return False

        previous_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
            self.held_expiry
        ).date()

        return self.Time.date() == previous_trading_day and self.Time.time() >= time(15, 45)

    def _handle_expiration_exit(self):
        if self.held_option is None or self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry.date():
            self.no_entry_dates.add(self.Time.date())
            self._submit_exit("expiration protection")

    def _submit_exit(self, reason):
        if self.held_option is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_option):
            self.Transactions.CancelOrder(order.Id)

        ticket = self.MarketOrder(self.held_option, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted: {reason} for {self.held_option}")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if any(order.Symbol == self.spy for order in self.Transactions.GetOpenOrders(self.spy)):
            return

        self.Debug("Unexpected SPY exercise/assignment position detected; liquidating")
        self.MarketOrder(self.spy, -quantity)

    def OnOrderEvent(self, order_event):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.held_expiry = order_event.Symbol.ID.Date
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_option} at {self.entry_price}"
                )
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.entry_order_id = None
                self.Debug(f"Entry canceled or invalid: {order_event.Symbol}")

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol} at {order_event.FillPrice}")
                self.held_option = None
                self.held_expiry = None
                self.entry_price = None
                self.exit_order_id = None
            elif order_event.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.exit_order_id = None
